--

CREATE TABLE public.users_user (
    id bigint NOT NULL,
    password character varying(128) NOT NULL,
    last_login timestamp with time zone,
    is_superuser boolean NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    deleted_at timestamp with time zone,
    uuid uuid NOT NULL,
    is_active boolean NOT NULL,
    username character varying(150) NOT NULL,
    email character varying(254) NOT NULL,
    first_name character varying(120) NOT NULL,
    last_name character varying(120) NOT NULL,
    document_type character varying(8) NOT NULL,
    document_number character varying(32) NOT NULL,
    gender character varying(1) NOT NULL,
    birth_date date,
    phone character varying(32) NOT NULL,
    mobile character varying(32) NOT NULL,
    address character varying(240) NOT NULL,
    city character varying(120) NOT NULL,
    photo character varying(100),
    is_staff boolean NOT NULL,
    email_verified boolean NOT NULL,
    must_change_password boolean NOT NULL,
    two_factor_enabled boolean NOT NULL,
    two_factor_enforced boolean NOT NULL,
    last_password_change timestamp with time zone,
    failed_login_attempts smallint NOT NULL,
    locked_until timestamp with time zone,
    last_login_ip inet,
    theme character varying(10) NOT NULL,
    notes text NOT NULL,
    created_by_id bigint,
    deleted_by_id bigint,
    institution_id bigint,
    updated_by_id bigint,
    role_id bigint,
    CONSTRAINT users_user_failed_login_attempts_check CHECK ((failed_login_attempts >= 0))
);

--
-- Name: users_user_groups; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users_user_groups (
    id bigint NOT NULL,
    user_id bigint NOT NULL,
    group_id integer NOT NULL
);

--
-- Name: users_user_groups_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.users_user_groups ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.users_user_groups_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: users_user_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.users_user ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
