    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: users_user_module_permission; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users_user_module_permission (
